/etc/freeradius/3.0/clients.conf:
# Campus RADIUS clients
client core-sw-01 {
	ipaddr = 198.51.100.31
	secret = SharedEstateKey2026
	shortname = core-sw
	nastype = cisco
}

client campus-wlc-01 {
	ipaddr = 10.100.0.30
	secret = SharedEstateKey2026
	shortname = wlc
	nastype = cisco
}

client branch-rtr-07 {
	ipaddr = 10.77.0.7
	secret = SharedEstateKey2026
	shortname = branch-rtr
}

client partner-nas {
	ipaddr = 203.0.113.44
	secret = P4rtnerUniqueKey!
	shortname = partner
}

client radsec-peer {
	ipaddr = 10.100.0.55
	secret = radsec
	proto = tls
	tls {
		ca_file = /etc/ssl/ca.pem
	}
}

/etc/freeradius/3.0/mods-available/eap:
eap {
	default_eap_type = peap
	timer_expire = 60

	md5 {
	}

	leap {
	}

	tls-config tls-common {
		tls_min_version = "1.0"
		tls_max_version = "1.2"
		private_key_password = EapKeyPassw0rd
		private_key_file = /etc/ssl/private/server.pem
	}

	tls {
		tls = tls-common
	}

	peap {
		tls = tls-common
		default_eap_type = mschapv2
	}

	mschapv2 {
	}
}

/etc/freeradius/3.0/radiusd.conf:
prefix = /usr
log {
	destination = files
	auth = yes
	auth_badpass = no
}

ldap {
	server = 'ldap://ldap.example.com'
	identity = 'cn=radius,dc=example,dc=com'
	password = LdapB1ndPass
	start_tls = no
	base_dn = 'dc=example,dc=com'
}

/etc/freeradius/3.0/sites-enabled/defaul:
server default {
	authorize {
		preprocess = 1
		chap = 1
		mschap = 1
		pap = 1
		eap = 1
	}
	authenticate {
		eap = 1
	}
}
